from typing import List
from collections import defaultdict

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        events = defaultdict(int)
        total_area = 0

        for _, y, l in squares:
            total_area += l * l
            events[y] += l
            events[y + l] -= l

        target_x2 = total_area
        area_x2 = 0
        active_width = 0

        ys = sorted(events)
        prev_y = ys[0]

        for y in ys:
            dy = y - prev_y

            if dy > 0:
                gain_x2 = 2 * dy * active_width

                if area_x2 + gain_x2 >= target_x2:
                    if active_width == 0:
                        return float(prev_y)
                    return prev_y + (target_x2 - area_x2) / (2.0 * active_width)

                area_x2 += gain_x2

            active_width += events[y]
            prev_y = y

            if area_x2 == target_x2:
                return float(prev_y)

        return float(prev_y)
